import{_ as e,o as d,c as o,aj as a}from"./framework.js";const h=JSON.parse('{"title":"Development | Development | Admin CMS","description":"The Development group centralizes templates and site-level resources for the site: View, Layout, Script, Style, Code, plus URL routing, forms, admin menus, authentication, Open API, SPA…","frontmatter":{"title":"Development | Development | Admin CMS","description":"The Development group centralizes templates and site-level resources for the site: View, Layout, Script, Style, Code, plus URL routing, forms, admin menus, authentication, Open API, SPA…","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/cms/development/index.html"}]]},"headers":[],"relativePath":"cms/development/index.md","filePath":"en/cms/development/index.md","lastUpdated":1781010536000}'),r={name:"cms/development/index.md"};function n(i,t,s,l,c,m){return d(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="development" tabindex="-1">Development <a class="header-anchor" href="#development" aria-label="Permalink to &quot;Development&quot;">​</a></h1><blockquote><p>Menu: <strong>Development</strong> group in the left sidebar (must be enabled in <strong>Edit Menu</strong>)<br> Route prefix: <code>/_Admin/development/...?SiteId={siteGuid}</code></p></blockquote><p>The <strong>Development</strong> group centralizes <strong>templates and site-level resources</strong> for the site: View, Layout, Script, Style, Code, plus URL routing, forms, admin menus, authentication, Open API, SPA multilingual, modules, scheduled jobs, and more. Together with <a href="./../site/pages.html">Pages</a> (page tree and visual editing), it forms the frontend implementation layer of a Kooboo site.</p><div class="tip custom-block"><p class="custom-block-title">Template engine docs</p><p>This series explains <strong>where to click and what to fill in</strong> in the admin; syntax and APIs are in the <a href="/kb-docs/templateEngine/">Template Engine</a> (Layout, View, Script, Style, etc.) and <a href="/kb-docs/api/">KScript API</a>. The two map one-to-one via object types in the menu.</p></div><div class="info custom-block"><p class="custom-block-title">Advanced menu</p><p>The Development group and most of its items are marked <strong>advanced</strong> in Edit Menu. If unchecked, this group does not appear in the left sidebar.</p></div><h2 id="how-to-open" tabindex="-1">How to Open <a class="header-anchor" href="#how-to-open" aria-label="Permalink to &quot;How to Open&quot;">​</a></h2><ol><li>In <a href="./../navigation.html#edit-menu">Edit Menu</a>, enable <strong>Development</strong> and the sub-items you need.</li><li>Expand <strong>Development</strong> in the left sidebar.</li></ol><h2 id="sub-menus-same-order-as-the-admin" tabindex="-1">Sub-menus (same order as the admin) <a class="header-anchor" href="#sub-menus-same-order-as-the-admin" aria-label="Permalink to &quot;Sub-menus (same order as the admin)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Menu</th><th>Path</th><th>Permission (feature)</th><th>Doc</th></tr></thead><tbody><tr><td>Views</td><td><code>/development/views</code></td><td><code>view</code></td><td><a href="./views.html">Views</a></td></tr><tr><td>Layouts</td><td><code>/development/layouts</code></td><td><code>layout</code></td><td><a href="./layouts.html">Layouts</a></td></tr><tr><td>Scripts</td><td><code>/development/scripts</code></td><td><code>script</code></td><td><a href="./scripts.html">Scripts</a></td></tr><tr><td>Styles</td><td><code>/development/styles</code></td><td><code>style</code></td><td><a href="./styles.html">Styles</a></td></tr><tr><td>Code</td><td><code>/development/code</code></td><td><code>code</code></td><td><a href="./code.html">Code</a></td></tr><tr><td>Code Log</td><td><code>/development/code-log</code></td><td><code>code·log</code></td><td><a href="./code-log.html">Code Log</a></td></tr><tr><td>Code Search</td><td><code>/development/code-search</code></td><td><code>code·view</code></td><td><a href="./code-search.html">Code Search</a></td></tr><tr><td>URL</td><td><code>/development/urls</code></td><td><code>link</code></td><td><a href="./urls.html">URL</a></td></tr><tr><td>Forms</td><td><code>/development/forms</code></td><td><code>form</code></td><td><a href="./forms.html">Forms</a></td></tr><tr><td>Menus</td><td><code>/development/menus</code></td><td><code>menu</code></td><td><a href="./menus.html">Menus</a></td></tr><tr><td>Authentication</td><td><code>/development/authentication</code></td><td><code>authentication</code></td><td><a href="./authentication.html">Authentication</a></td></tr><tr><td>Open API</td><td><code>/development/openapis</code></td><td><code>openApi</code></td><td><a href="./openapis.html">Open API</a></td></tr><tr><td>SPA Multilingual</td><td><code>/development/spamultilingual</code></td><td><code>spaMultilingual</code></td><td><a href="./spa-multilingual.html">SPA Multilingual</a></td></tr><tr><td>Modules</td><td><code>/development/modules</code></td><td><code>module</code></td><td><a href="./modules.html">Modules</a></td></tr><tr><td>Jobs</td><td><code>/development/jobs</code></td><td><code>job</code></td><td><a href="./jobs.html">Jobs</a></td></tr></tbody></table><h3 id="development-reference-template-engine-api" tabindex="-1">Development reference (template engine / API) <a class="header-anchor" href="#development-reference-template-engine-api" aria-label="Permalink to &quot;Development reference (template engine / API)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Menu</th><th>Development docs</th></tr></thead><tbody><tr><td>Views</td><td><a href="/kb-docs/templateEngine/view/">View</a> · <code>k.site.views</code></td></tr><tr><td>Layouts</td><td><a href="/kb-docs/templateEngine/layout/">Layout</a></td></tr><tr><td>Scripts</td><td><a href="/kb-docs/templateEngine/js/">Script</a></td></tr><tr><td>Styles</td><td><a href="/kb-docs/templateEngine/css/">Style</a></td></tr><tr><td>Code</td><td><code>k.site.codes</code> (API)</td></tr><tr><td>Menus</td><td><a href="/kb-docs/api/site/menu.html">k.site.menus</a></td></tr><tr><td>Authentication</td><td><a href="/kb-docs/api/security/">k.security.jwt</a> · <a href="/kb-docs/api/response/">k.response</a></td></tr><tr><td>Open API</td><td><a href="/kb-docs/api/openapi/">k.openApi</a></td></tr><tr><td>SPA Multilingual</td><td><a href="/kb-docs/api/spa-multilingual/">SPA Multilingual API</a></td></tr><tr><td>Modules</td><td><a href="/kb-docs/api/module/">k.module</a></td></tr><tr><td>Jobs</td><td><a href="/kb-docs/api/site/job.html">k.site.runJob</a></td></tr></tbody></table><h2 id="edit-routes-without-sidebar-menu-entries" tabindex="-1">Edit routes without sidebar menu entries <a class="header-anchor" href="#edit-routes-without-sidebar-menu-entries" aria-label="Permalink to &quot;Edit routes without sidebar menu entries&quot;">​</a></h2><p>The following pages are opened from list <strong>Edit</strong> actions; breadcrumbs still belong to the corresponding menu item:</p><table tabindex="0"><thead><tr><th>Route</th><th>Description</th></tr></thead><tbody><tr><td><code>/development/layout/edit</code></td><td>Edit Layout</td></tr><tr><td><code>/development/view/edit</code></td><td>Edit View</td></tr><tr><td><code>/development/script/edit</code></td><td>Edit Script</td></tr><tr><td><code>/development/style/edit</code></td><td>Edit Style</td></tr><tr><td><code>/development/code/edit</code></td><td>Edit Code</td></tr><tr><td><code>/development/form/edit</code></td><td>Edit form</td></tr><tr><td><code>/development/menu/edit</code></td><td>Edit admin menu item</td></tr><tr><td><code>/development/openapi/edit</code></td><td>Edit Open API definition</td></tr><tr><td><code>/development/form-values</code></td><td>Form submission data (<code>activeMenu: forms</code>)</td></tr><tr><td><code>/development/openapi/authorizes</code></td><td>Open API authorization records</td></tr><tr><td><code>/development/module-menu/:module</code></td><td>Enter installed module sub-menu</td></tr></tbody></table><h2 id="relationship-to-the-pages-module" tabindex="-1">Relationship to the Pages module <a class="header-anchor" href="#relationship-to-the-pages-module" aria-label="Permalink to &quot;Relationship to the Pages module&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>Entry</th><th>Doc</th></tr></thead><tbody><tr><td>Page tree, publish, rich text / designer</td><td><strong>Site → Pages</strong></td><td><a href="./../site/pages.html">Pages</a></td></tr><tr><td>Edit HTML online, bind View/Layout</td><td>Page list <strong>Inline Edit</strong></td><td><a href="./../site/pages-inline-edit.html">Inline Edit</a></td></tr><tr><td>Edit page code files directly</td><td>Page <strong>Edit Code</strong></td><td><a href="./../site/pages-edit-code.html">Edit Code</a></td></tr><tr><td>Site-level View/Layout library</td><td><strong>Development → Views / Layouts</strong></td><td><a href="./layouts.html">Layouts</a> · <a href="./views.html">Views</a></td></tr></tbody></table><p>Page designer routes (such as <code>/_Admin/page/edit</code>, <code>/_Admin/page/design</code>) are entered from the <strong>Pages</strong> list, not under the Development group.</p><h2 id="suggested-reading-order" tabindex="-1">Suggested reading order <a class="header-anchor" href="#suggested-reading-order" aria-label="Permalink to &quot;Suggested reading order&quot;">​</a></h2><p>When using development capabilities from a site-building perspective, a common order is:</p><ol><li><strong>Layouts</strong> — page shell and shared structure</li><li><strong>Views</strong> — reusable fragments referenced by pages or Layouts</li><li><strong>Scripts / Styles</strong> — site-level JS/CSS resources</li><li><strong>URLs</strong> — custom routing and bindings</li><li><strong>Forms / Menus / Authentication</strong> — forms, admin menus, and login methods (as needed)</li><li><strong>Open API / SPA Multilingual / Modules / Jobs</strong> — integration and extensions</li></ol><p>See each sub-page for specific steps.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Doc</th><th>Description</th></tr></thead><tbody><tr><td><a href="./../navigation.html">Site admin menu overview</a></td><td>Full menu tree</td></tr><tr><td><a href="./../site/pages.html">Pages</a></td><td>Pages and visual editing</td></tr><tr><td><a href="./../operations/">Operations</a></td><td>Runtime observability (separate from development implementation)</td></tr><tr><td><a href="/kb-docs/templateEngine/">Template Engine</a></td><td>Template syntax and concepts</td></tr><tr><td><a href="/kb-docs/api/">KScript API</a></td><td>Script APIs</td></tr></tbody></table>',23)])])}const u=e(r,[["render",n]]);export{h as __pageData,u as default};
